// Option selection (runtime 0.90.0, `selection-rule.v1.md`): the selection block codec, the v5 field 9 it
// frames, and the `proposal` explanation word. `conformance/selection_rule_v1_vectors.json` is
// seam-runtime's fixture, vendored verbatim (generated by its independent stdlib-only
// `scripts/selection_rule_v1_vectors.py`). Every `rule_cases` vector drives `decide` (§3) and every
// `sealed_cases` vector drives `verifySelection` (§5 steps 6-9), by result name, exactly as the Python SDK's
// `test_selection_rule_v1.py` does; `verifyTct` is then driven end to end over really-signed voter records.

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { create } from "@bufbuild/protobuf";
import { mintSealKeyTct } from "./seal_key_mint.js";
import { ed25519 } from "@noble/curves/ed25519";
import {
  type Commitment,
  type ExplanationEntryInput,
  type SelectionBlock,
  type SelectionRuleRecord,
  aidFromPubkey,
  decide,
  explanationDigest,
  seamCommitmentDigest,
  selectionBody,
  selectionDecide,
  selectionDigest,
  signVoterPop,
  verifySelection,
  verifyTct,
} from "../src/crypto.js";
import { commitmentView } from "../src/client.js";
import { CommitmentSchema, ExplanationKind, VoterVerification } from "../gen/seam/api/v1/seam_pb.js";

const V = JSON.parse(
  readFileSync(new URL("../../conformance/selection_rule_v1_vectors.json", import.meta.url), "utf8"),
);
const hex = (b: Uint8Array) => Buffer.from(b).toString("hex");
const CODEC = V.codec as { block: SelectionBlock; body: string; selection_digest: string; field_9: string };
const VERIFIED = (V.sealed_cases as { name: string; block: SelectionBlock; entries: ExplanationEntryInput[]; action: string }[]).find(
  (c) => c.name === "verified",
)!;
const CASES = V.commitment_digest_v5.cases as {
  name: string;
  commitment: Record<string, any>;
  explanation_digest: string;
  selection_digest: string | null;
  certificate_digest: string | null;
  governing_doc_sha256: string | null;
  commitment_digest: string;
}[];

test("the codec block encodes to the vector body, digest and field 9", () => {
  const body = selectionBody(CODEC.block);
  assert.equal(hex(body), CODEC.body);
  assert.equal(body.length, 422);
  const d = selectionDigest(body);
  assert.equal(hex(d), CODEC.selection_digest);
  assert.equal("01" + "0000000000000020" + hex(d), CODEC.field_9);
});

test("the verified case's seven entries (proposal word included) give the vector's explanation digest", () => {
  const populated = CASES.find((c) => c.name === "populated_selection_governed")!;
  assert.equal(hex(explanationDigest(VERIFIED.entries)), populated.explanation_digest);
  assert.equal(populated.explanation_digest, "40a4e742ffce841dcb2deb0ee6912c590a7268068117dd593bbd11bb4f76e34c");
});

test("every commitment_digest_v5 case, field 9 from the slot and from the block", () => {
  for (const c of CASES) {
    const base = {
      ...c.commitment,
      explanation_digest: c.explanation_digest,
      certificate_digest: c.certificate_digest,
      governing_doc_sha256: c.governing_doc_sha256,
    } as any;
    assert.equal(seamCommitmentDigest({ ...base, selection_digest: c.selection_digest }), c.commitment_digest, c.name);
    if (c.selection_digest !== null) {
      assert.equal(seamCommitmentDigest({ ...base, selection: CODEC.block }), c.commitment_digest, `${c.name} (block)`);
      assert.throws(() => seamCommitmentDigest({ ...base, selection: CODEC.block, selection_digest: c.selection_digest }));
    }
  }
});

test("a block the runtime could not have sealed is refused, never hashed", () => {
  const b = CODEC.block;
  const bad: [string, SelectionBlock][] = [
    ["weights descending", { ...b, weights: [{ participant: "carol", weight: 1 }, { participant: "bob", weight: 2 }] }],
    ["weights duplicate", { ...b, weights: [{ participant: "bob", weight: 1 }, { participant: "bob", weight: 2 }] }],
    ["rules_digest 31 bytes", { ...b, rules_digest: (b.rules_digest as string).slice(2) }],
    ["empty winner", { ...b, winner_proposal_id: "" }],
    ["u32 overflow", { ...b, min_ballots: 2 ** 32 }],
    ["negative weight", { ...b, default_weight: -1 }],
  ];
  for (const [name, blk] of bad) assert.throws(() => selectionBody(blk), name);
  // Ascending is by UTF-8 BYTES: "Z" (0x5a) sorts before "a" (0x61), and "é" (0xc3 0xa9) after "z".
  selectionBody({ ...b, weights: [{ participant: "Z", weight: 1 }, { participant: "a", weight: 1 }, { participant: "é", weight: 1 }] });
});

const KINDS: Record<string, ExplanationKind> = {
  vote: ExplanationKind.VOTE,
  proposal: ExplanationKind.PROPOSAL,
};

function servedProto(withSelection: boolean) {
  const c = CASES.find((x) => x.name === "populated_selection_governed")!.commitment;
  const b = CODEC.block;
  return create(CommitmentSchema, {
    id: c.id,
    action: c.action,
    authority: c.authority,
    authMethod: c.auth_method,
    trustBasis: c.trust_basis,
    committer: c.committer,
    governingDocSha256: Buffer.from(CASES[1].governing_doc_sha256!, "hex"),
    ...(withSelection
      ? {
          selection: {
            rule: b.rule,
            ruleVersion: b.rule_version,
            defaultWeight: b.default_weight,
            weights: b.weights.map((w) => ({ participant: w.participant, weight: w.weight })),
            tie: b.tie,
            abstention: b.abstention,
            minBallots: b.min_ballots,
            policyVersion: b.policy_version,
            rulesDigest: Buffer.from(b.rules_digest as string, "hex"),
            participants: [...b.participants],
            onBehalfOf: [...b.on_behalf_of],
            context: b.context.map((x) => ({ ctxRef: x.ctx_ref, contentHash: x.content_hash })),
            winnerProposalId: b.winner_proposal_id,
          },
        }
      : {}),
    explanation: VERIFIED.entries.map((e) => ({
      kind: KINDS[e.kind],
      participant: e.participant,
      proposalId: e.proposal_id,
      value: e.value,
      reason: e.reason,
      ...(e.voter_verification
        ? {
            voterVerification: {
              method: VoterVerification.POP,
              principal: e.voter_verification.principal,
              contentDigest: Buffer.from(e.voter_verification.content_digest as string, "hex"),
              issuedAtMs: BigInt(e.voter_verification.issued_at_ms),
              expiresAtMs: BigInt(e.voter_verification.expires_at_ms),
              signature: Buffer.from(e.voter_verification.signature as string, "hex"),
              signerCertificate: Buffer.from(e.voter_verification.signer_certificate as string, "hex"),
              tenant: e.voter_verification.tenant,
              namespace: e.voter_verification.namespace,
              sessionId: e.voter_verification.session_id,
              openedAtMillis: BigInt(e.voter_verification.opened_at_millis),
              issuer: e.voter_verification.issuer,
              audience: e.voter_verification.audience,
              acceptedAtMs: BigInt(e.voter_verification.accepted_at_ms),
            },
          }
        : {}),
    })),
  });
}

test("commitmentView frames field 9 from the served selection, with explicit presence", () => {
  const governed = CASES.find((c) => c.name === "populated_selection_governed")!;
  const stripped = CASES.find((c) => c.name === "populated_selection_stripped")!;
  const view = commitmentView(servedProto(true));
  assert.equal(view.explanation![0].kind, "proposal");
  assert.equal(seamCommitmentDigest(view), governed.commitment_digest);
  // Absent selection is "not a selection decision": field 9 = 0x00.
  const plain = commitmentView(servedProto(false));
  assert.equal(plain.selection, null);
  assert.equal(seamCommitmentDigest(plain), stripped.commitment_digest);
  // An edited weight moves the digest (a TCT holder sees it).
  const m = servedProto(true);
  m.selection!.weights[0].weight = 3;
  assert.notEqual(seamCommitmentDigest(commitmentView(m)), governed.commitment_digest);
  // A served block the runtime could not have sealed fails closed.
  m.selection!.winnerProposalId = "";
  assert.throws(() => seamCommitmentDigest(commitmentView(m)));
});

// ── decide() (§3): every rule_cases vector ───────────────────────────────────────────────────────────

const RULE_CASES = V.rule_cases as { name: string; record: SelectionRuleRecord; entries: ExplanationEntryInput[]; expect: Record<string, unknown> }[];
const SEALED_CASES = V.sealed_cases as {
  name: string;
  block: SelectionBlock;
  entries: ExplanationEntryInput[];
  action: string;
  expect: Record<string, unknown>;
}[];

test("all 30 rule_cases and all 13 sealed_cases are present", () => {
  assert.equal(RULE_CASES.length, 30);
  assert.equal(SEALED_CASES.length, 13);
  assert.equal(selectionDecide, decide);
});

for (const c of RULE_CASES) {
  test(`rule_cases/${c.name}`, () => {
    const got = decide(c.record, c.entries) as Record<string, unknown>;
    assert.equal(got.result, c.expect.result);
    for (const [k, v] of Object.entries(c.expect)) assert.deepEqual(got[k], v, k);
  });
}

// ── verifySelection (§5 steps 6-9): every sealed_cases vector, by result name ────────────────────────

for (const c of SEALED_CASES) {
  test(`sealed_cases/${c.name}`, () => {
    const got = verifySelection(c.block, c.entries, c.action);
    const want = c.expect;
    assert.equal(got.result, want.result);
    if ("at" in want) assert.equal(got.at, want.at);
    if ("recomputed" in want) assert.equal(got.recomputed, want.recomputed);
    if (want.result === "verified") {
      assert.ok(got.ok);
      assert.equal(got.winner_proposal_id, want.winner_proposal_id);
      assert.equal(got.votes_linked, want.votes_linked);
    } else {
      assert.equal(got.ok, false);
    }
  });
}

// ── end to end through verifyTct ─────────────────────────────────────────────────────────────────────
// The vector's voter signatures are placeholders, and an ESM module cannot have its internal
// `verifyCommitmentVoters` stubbed, so the verified case's votes are re-signed here with real per-participant
// keys over the vector's own content digests. Every step — the TCT, the voter PoPs, field 9 and steps 6-9 —
// then runs for real.

const ISSUER_SEED = new Uint8Array(32).map((_, i) => i);
const ISSUER = aidFromPubkey(ed25519.getPublicKey(ISSUER_SEED));
const b64 = (b: Uint8Array | string) => Buffer.from(b).toString("base64url");

function tct(digest: string): string {
  // S-4: signed by the seeded seal key the issuer certifies over [0, 900_000] ms, iat = 0.
  return mintSealKeyTct({
    issuerSeed: ISSUER_SEED,
    certIssuerAid: ISSUER,
    statement: { type: "seam:commitment", commitment_digest: digest },
  });
}

function signedEntries(): ExplanationEntryInput[] {
  return VERIFIED.entries.map((e) => {
    const vv = e.voter_verification;
    if (!vv) return e;
    const seed = new Uint8Array(Buffer.from(e.participant.padEnd(32, "#").slice(0, 32)));
    const target = {
      issuer: ISSUER,
      tenant: vv.tenant,
      namespace: vv.namespace,
      sessionId: vv.session_id,
      openedAtMillis: BigInt(vv.opened_at_millis),
      audience: vv.audience,
    };
    const proof = signVoterPop(
      seed,
      target,
      new Uint8Array(Buffer.from(vv.content_digest as string, "hex")),
      { kind: e.kind, participant: e.participant, proposalId: e.proposal_id, value: e.value, reason: e.reason },
      { issuedAtMs: BigInt(vv.issued_at_ms), expiresAtMs: BigInt(vv.expires_at_ms) },
    );
    return { ...e, voter_verification: { ...vv, issuer: ISSUER, principal: proof.voterAid, signature: proof.signature } };
  });
}

function selectionCommitment(over: Partial<Commitment> = {}): Commitment {
  const governed = CASES.find((c) => c.name === "populated_selection_governed")!;
  return {
    ...(governed.commitment as Commitment),
    governing_doc_sha256: governed.governing_doc_sha256,
    explanation: signedEntries(),
    selection: VERIFIED.block,
    ...over,
  };
}

test("a selection commitment verifies end to end", () => {
  const c = selectionCommitment();
  assert.equal(verifySelection(c.selection!, c.explanation!, c.action).ok, true);
  assert.equal(verifyTct(ISSUER, tct(seamCommitmentDigest(c)), c, 0), true);
});

test("a losing action under a valid TCT fails the winner recompute", () => {
  const c = selectionCommitment({ action: "rate 5%" });
  assert.equal(verifyTct(ISSUER, tct(seamCommitmentDigest(c)), c, 0), false);
});

test("a tampered winner under a valid TCT fails the winner recompute", () => {
  // The TCT binds what was sealed; the recompute catches a seal whose winner the rule never chose.
  const c = selectionCommitment({ selection: { ...VERIFIED.block, winner_proposal_id: "p1" }, action: "rate 5%" });
  assert.equal(verifySelection(c.selection!, c.explanation!, c.action).result, "selection_winner_mismatch");
  assert.equal(verifyTct(ISSUER, tct(seamCommitmentDigest(c)), c, 0), false);
});

test("a stripped or edited block fails the TCT", () => {
  const c = selectionCommitment();
  const jws = tct(seamCommitmentDigest(c));
  assert.equal(verifyTct(ISSUER, jws, { ...c, selection: null }, 0), false);
  const edited = { ...VERIFIED.block, weights: VERIFIED.block.weights.map((w, i) => (i === 0 ? { ...w, weight: 3 } : w)) };
  assert.equal(verifyTct(ISSUER, jws, { ...c, selection: edited }, 0), false);
});

test("a selection block without explanation entries fails closed", () => {
  const c = selectionCommitment();
  const jws = tct(seamCommitmentDigest(c));
  const { explanation, ...rest } = c;
  const bare: Commitment = { ...rest, explanation_digest: explanationDigest(explanation!) };
  // The digest still binds (field 8 from the published digest, field 9 from the block) ...
  assert.equal(seamCommitmentDigest(bare), seamCommitmentDigest(c));
  // ... but the winner cannot be recomputed without the entries, so it never passes as if it had been.
  assert.equal(verifyTct(ISSUER, jws, bare, 0), false);
  // Control: the same commitment with field 9 as a bare digest (no block) is not a selection check.
  const slotOnly: Commitment = { ...bare, selection: null, selection_digest: selectionDigest(selectionBody(VERIFIED.block)) };
  assert.equal(verifyTct(ISSUER, jws, slotOnly, 0), true);
});
